test-case.test:

let $config := <configuration edition="PE" xmlns="http://saxon.sf.net/ns/configuration">
                    <localizations defaultLanguage="de" defaultCountry="DE">
                        <localization lang="de" class="net.sf.saxon.option.local.Numberer_de"/>
                    </localizations>
                </configuration>

return transform (
    map{
        "stylesheet-node":$xsl, 
        "initial-template":QName('', 'main'),
        "vendor-options": map{
                QName('http://saxon.sf.net/', 'configuration'): $config
                } 
   })

let $configDE := <configuration edition="PE" xmlns="http://saxon.sf.net/ns/configuration"> <localizations defaultLanguage="de" defaultCountry="DE"> <localization lang="de" class="net.sf.saxon.option.local.Numberer_de"/> </localizations> </configuration>,
$configEN := <configuration edition="PE" xmlns="http://saxon.sf.net/ns/configuration"> <localizations defaultLanguage="en" defaultCountry="GB"> <localization lang="de" class="net.sf.saxon.option.local.Numberer_de"/> </localizations> </configuration>,
$out1 := transform( map{"stylesheet-node":$xsl, "initial-template":QName('','main'), "cache": false(), "vendor-options": map{ QName('http://saxon.sf.net/', 'configuration'): $configDE } }),
$out2 := transform( map{"stylesheet-node":$xsl, "initial-template":QName('', 'main'), "cache": false(), "vendor-options": map{ QName('http://saxon.sf.net/', 'configuration'): $configEN} })
return concat($out1?output//out, ' ' , $out2?output//out)
